(function(){
  var root=document.querySelector('.s-game_section');
  if(!root||root.dataset.inited)return;root.dataset.inited='1';
  function $(s){return root.querySelector(s);}
  var cv=$('.js-canvas'),ctx=cv&&cv.getContext('2d');if(!cv||!ctx)return;
  var W=360,H=640,GROUND=506,WORLD=1900,TILE=60;
  var overlay=$('.js-overlay'),panels=Array.prototype.slice.call(root.querySelectorAll('.js-panel'));
  var promptEl=$('.js-prompt'),heartsEl=$('.js-hearts'),progressEl=$('.js-progress');
  var countdownEl=$('.js-countdown'),timer=null;
  var stickZone=$('.js-stickZone'),stickThumb=$('.js-stickThumb');
  var IDS=['hero_idle','hero_run1','hero_run2','hero_run3','hero_run4','hero_jump','tile_ground','tile_platform','tile_float','flag_off','flag_on','lamp_post','coin_heart','door_finish','bg_hills','lantern_fly1','lantern_fly2','lantern_fly3','lantern_fly4','lantern_fly5','lantern_fly6','bird_fly1','bird_fly2','bird_fly3','bird_fly4'];
  var IMG={};IDS.forEach(function(id){var im=new Image(),el=root.querySelector('[data-imgid="'+id+'"]');if(el)im.src=el.currentSrc||el.src||'';IMG[id]=im;});
  if('MutationObserver' in window){var pre=$('.js-preload');if(pre)new MutationObserver(function(muts){muts.forEach(function(m){var t=m.target,id=t.getAttribute&&t.getAttribute('data-imgid');if(id&&IMG[id])IMG[id].src=t.currentSrc||t.src||'';});}).observe(pre,{attributes:true,subtree:true,attributeFilter:['src']});}
  function draw(img,x,y,w,h){x=Math.round(x);y=Math.round(y);w=Math.round(w);h=Math.round(h);if(img&&img.complete&&img.naturalWidth>0){try{ctx.drawImage(img,x,y,w,h);return true;}catch(e){}}return false;}
  function box(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));}
  function rrect(x,y,w,h,r){x=Math.round(x);y=Math.round(y);w=Math.round(w);h=Math.round(h);r=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();}

  var grounds=[
    {x:0,w:455},
    {x:550,w:360},
    {x:1010,w:360},
    {x:1480,w:420}
  ];
  var plats=[
    {x:478,y:450,w:56,h:26,float:true},
    {x:700,y:414,w:72,h:28,float:true},
    {x:932,y:450,w:56,h:26,float:true},
    {x:1388,y:450,w:56,h:26,float:true},
    {x:1600,y:414,w:72,h:28,float:true}
  ];
  var flags=[
    {x:220,baseY:GROUND+4,panel:'couple',step:0,done:false},
    {x:755,baseY:GROUND+4,panel:'datetime',step:1,done:false},
    {x:1255,baseY:GROUND+4,panel:'venue',step:2,done:false}
  ];
  var door={x:1770,baseY:GROUND+6,panel:'finale'};
  var coins=[
    {x:315,y:474,taken:false},{x:506,y:404,taken:false},{x:736,y:368,taken:false},
    {x:960,y:404,taken:false},{x:1120,y:474,taken:false},{x:1416,y:404,taken:false},
    {x:1615,y:368,taken:false},{x:1710,y:474,taken:false}
  ];
  var lamps=[
    {x:90,baseY:GROUND+6},
    {x:622,baseY:GROUND+6},
    {x:1118,baseY:GROUND+6},
    {x:1668,baseY:GROUND+6}
  ];
  var flyLanterns=[{x:180,y:188,s:.78,p:.2},{x:470,y:138,s:.58,p:1.4},{x:820,y:212,s:.72,p:2.7},{x:1180,y:130,s:.56,p:4.2},{x:1500,y:198,s:.76,p:5.3},{x:1760,y:145,s:.6,p:6.4}];
  var birds=[{x:290,y:126,s:.70,v:18,p:.2},{x:1000,y:90,s:.58,v:25,p:2.1},{x:1620,y:146,s:.66,v:20,p:4.4}];

  var hearts=0,cam=0,T=0,currentStep=0,toastUntil=0,toastText='';
  var P={x:42,y:GROUND-36,w:22,h:36,vy:0,face:1,ground:false,anim:0};
  var HERO_DRAW={w:42,h:66,ox:-10,oy:-18};
  var safe={x:P.x,y:P.y};
  var input={l:0,r:0},jumpQueued=false;

  function isField(t){return t&&(t.tagName==='INPUT'||t.tagName==='TEXTAREA'||t.tagName==='SELECT');}
  document.addEventListener('keydown',function(e){if(isField(e.target))return;if(overlay&&!overlay.hidden)return;var k=e.key;if(k==='ArrowLeft'||k==='a'||k==='A'){input.l=1;e.preventDefault();}else if(k==='ArrowRight'||k==='d'||k==='D'){input.r=1;e.preventDefault();}else if(k==='ArrowUp'||k==='w'||k==='W'||k===' '){jumpQueued=true;e.preventDefault();}else if(k==='e'||k==='E'||k==='Enter'){doInteract();}});
  document.addEventListener('keyup',function(e){var k=e.key;if(k==='ArrowLeft'||k==='a'||k==='A')input.l=0;else if(k==='ArrowRight'||k==='d'||k==='D')input.r=0;});

  root.querySelectorAll('.js-btn').forEach(function(b){var k=b.getAttribute('data-k');function on(e){e.preventDefault();if(k==='jump')jumpQueued=true;else if(k==='act')doInteract();else input[k]=1;}function off(e){if(e)e.preventDefault();if(k!=='jump'&&k!=='act')input[k]=0;}b.addEventListener('touchstart',on,{passive:false});b.addEventListener('touchend',off);b.addEventListener('touchcancel',off);b.addEventListener('mousedown',on);b.addEventListener('mouseup',off);b.addEventListener('mouseleave',off);});

  function stickCenter(){if(stickThumb)stickThumb.style.transform='translate(-50%,-50%)';}
  function setStick(dx,dy,limit){if(!stickThumb)return;stickThumb.style.transform='translate(calc(-50% + '+Math.round(dx)+'px), calc(-50% + '+Math.round(dy)+'px))';var nx=dx/limit,ny=dy/limit;input.l=nx<-0.24?1:0;input.r=nx>0.24?1:0;if(ny<-0.68&&P.ground)jumpQueued=true;}
  if(stickZone&&stickThumb){var stickId=null,stickActive=false;function resetStick(){stickActive=false;stickId=null;input.l=0;input.r=0;stickCenter();}function handleStick(clientX,clientY){var r=stickZone.getBoundingClientRect();var cx=r.left+r.width/2,cy=r.top+r.height/2;var dx=clientX-cx,dy=clientY-cy;var limit=Math.min(r.width,r.height)*0.28;var mag=Math.sqrt(dx*dx+dy*dy)||1;if(mag>limit){dx=dx/mag*limit;dy=dy/mag*limit;}setStick(dx,dy,limit);}stickZone.addEventListener('pointerdown',function(e){stickActive=true;stickId=e.pointerId;stickZone.setPointerCapture&&stickZone.setPointerCapture(e.pointerId);handleStick(e.clientX,e.clientY);e.preventDefault();});stickZone.addEventListener('pointermove',function(e){if(!stickActive||e.pointerId!==stickId)return;handleStick(e.clientX,e.clientY);e.preventDefault();});['pointerup','pointercancel','lostpointercapture'].forEach(function(ev){stickZone.addEventListener(ev,function(e){if(stickId!==null&&e.pointerId!==undefined&&e.pointerId!==stickId&&ev!=='lostpointercapture')return;resetStick();});});stickCenter();}

  function near(){var cx=P.x+P.w/2,best=null,bd=1e9;flags.concat([door]).forEach(function(f){var d=Math.abs(cx-f.x);if(d<68&&d<bd){bd=d;best=f;}});return best;}
  function toast(t){toastText=t;toastUntil=T+2.1;}
  function doInteract(){var f=near();if(!f)return;if(f===door){if(currentStep<flags.length){toast('Selesaikan semua stasiun terlebih dahulu ♥');return;}openPanel('finale');return;}if(f.step!==currentStep){if(f.step<currentStep)openPanel(f.panel);else toast('Stasiun ini masih terkunci. Ikuti urutan perjalanan.');return;}f.done=true;currentStep++;updateProgress();openPanel(f.panel);}
  function updateProgress(){if(progressEl)progressEl.textContent=currentStep+'/3 STASIUN';}
  function timezoneOffset(tz){return tz==='WIT'?9:tz==='WITA'?8:7;}
  function currentDateTime(){var dEl=root.querySelector('[data-field="event_date"]'),tEl=root.querySelector('[data-field="event_time"]'),zEl=root.querySelector('[data-field="event_timezone"]');var d=dEl?dEl.textContent.trim():'',t=tEl?tEl.textContent.trim():'00:00',z=zEl?zEl.textContent.trim():'WIB';if(!d)return null;var parts=d.split('-'),tp=t.split(':');if(parts.length!==3)return null;var utc=Date.UTC(+parts[0],+parts[1]-1,+parts[2],+(tp[0]||0)-timezoneOffset(z),+(tp[1]||0),0);var dt=new Date(utc);return isNaN(dt.getTime())?null:dt;}
  function tick(){if(!countdownEl)return;var target=currentDateTime();if(!target){countdownEl.textContent='';return;}var diff=target.getTime()-Date.now();if(diff<=0){countdownEl.textContent='Hari bahagia telah tiba!';return;}var s=Math.floor(diff/1000),dd=Math.floor(s/86400),hh=Math.floor(s%86400/3600),mm=Math.floor(s%3600/60),ss=s%60;countdownEl.textContent=dd+' hari · '+hh+' jam · '+mm+' menit · '+ss+' detik';}
  function openPanel(name){panels.forEach(function(p){p.hidden=p.getAttribute('data-panel')!==name;});overlay.hidden=false;if(name==='datetime'){tick();if(timer)clearInterval(timer);timer=setInterval(tick,1000);}var m=root.querySelector('.s-game_section__modal');if(m)m.scrollTop=0;}
  function closePanel(){overlay.hidden=true;if(timer){clearInterval(timer);timer=null;}}
  root.querySelectorAll('.js-close').forEach(function(b){b.addEventListener('click',closePanel);});overlay.addEventListener('click',function(e){if(e.target===overlay)closePanel();});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&overlay&&!overlay.hidden)closePanel();});

  function onTopOf(rect){return P.vy>=0&&P.x+P.w>rect.x&&P.x<rect.x+rect.w;}
  function collide(){P.ground=false;for(var i=0;i<plats.length;i++){var pl=plats[i];if(onTopOf(pl)){var feet=P.y+P.h;if(feet>=pl.y&&feet<=pl.y+Math.max(14,P.vy+3)){P.y=pl.y-P.h;P.vy=0;P.ground=true;}}}for(var g=0;g<grounds.length;g++){var gr=grounds[g];if(onTopOf(gr)){var feet2=P.y+P.h;if(feet2>=GROUND&&feet2<=GROUND+Math.max(14,P.vy+3)){P.y=GROUND-P.h;P.vy=0;P.ground=true;}}}if(P.ground){safe.x=P.x;safe.y=P.y;}}
  function update(dt){var mv=0;if(input.l)mv--;if(input.r)mv++;P.x+=mv*3.35;if(mv!==0)P.face=mv;if(mv!==0&&P.ground)P.anim+=dt*9.5;if(P.x<0)P.x=0;if(P.x>WORLD-P.w)P.x=WORLD-P.w;P.vy+=0.60;if(P.vy>13)P.vy=13;if(jumpQueued){if(P.ground){P.vy=-12.6;P.ground=false;}jumpQueued=false;}P.y+=P.vy;collide();if(P.y>H+180){P.x=safe.x;P.y=safe.y;P.vy=0;}var cx=P.x+P.w/2,cy=P.y+P.h/2;coins.forEach(function(c){if(!c.taken&&Math.abs(cx-c.x)<28&&Math.abs(cy-c.y)<32){c.taken=true;hearts++;if(heartsEl)heartsEl.textContent='♥ '+hearts+'/8';}});birds.forEach(function(b){b.x+=b.v*dt;if(b.x>WORLD+120)b.x=-160;});T+=dt;var tx=P.x+P.w/2-W*0.48;if(tx<0)tx=0;if(tx>WORLD-W)tx=WORLD-W;cam+=(tx-cam)*Math.min(1,dt*7);}  
  function heroFrame(){if(!P.ground)return IMG.hero_jump;if(input.l||input.r){var f=[IMG.hero_run1,IMG.hero_run2,IMG.hero_run3,IMG.hero_run4];return f[Math.floor(P.anim)%4];}return IMG.hero_idle;}
  function vis(x,w){return x+w>cam-100&&x<cam+W+100;}
  function renderGroundTile(x){var sx=Math.round(x-cam);if(!draw(IMG.tile_ground,sx,GROUND,TILE+2,62))box(sx,GROUND,TILE+2,62,'#e9d6a4');}
  function render(){ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,W,H);box(0,0,W,H,'#101735');
    var bg=IMG.bg_hills;var bw=980,bh=490,off=-((cam*0.12)%bw);for(var bx=off-bw;bx<W+bw;bx+=bw){if(!draw(bg,bx,-2,bw,bh))box(bx,0,bw,bh,'#1b2351');}
    var grad=ctx.createLinearGradient(0,355,0,H);grad.addColorStop(0,'rgba(16,23,53,0)');grad.addColorStop(.55,'rgba(16,23,53,.16)');grad.addColorStop(1,'rgba(8,12,31,.72)');ctx.fillStyle=grad;ctx.fillRect(0,325,W,H-325);

    flyLanterns.forEach(function(l,i){var yy=l.y+Math.sin(T*0.9+l.p)*13,xx=l.x+Math.sin(T*0.35+l.p)*18;if(!vis(xx,40))return;var frames=[IMG.lantern_fly1,IMG.lantern_fly2,IMG.lantern_fly3,IMG.lantern_fly4,IMG.lantern_fly5,IMG.lantern_fly6],im=frames[Math.floor((T*5+i)%frames.length)];draw(im,xx-cam*0.55,yy,40*l.s,54*l.s);});
    birds.forEach(function(b){if(!vis(b.x,52))return;var fr=[IMG.bird_fly1,IMG.bird_fly2,IMG.bird_fly3,IMG.bird_fly4],im=fr[Math.floor((T*7+b.p)%4)];draw(im,b.x-cam*0.62,b.y+Math.sin(T*1.4+b.p)*6,50*b.s,36*b.s);});

    grounds.forEach(function(gr){if(!vis(gr.x,gr.w))return;var end=gr.x+gr.w;for(var x=gr.x;x<end;x+=TILE){renderGroundTile(x);}});
    plats.forEach(function(pl){if(!vis(pl.x,pl.w))return;if(pl.float){if(!draw(IMG.tile_float,pl.x-cam,pl.y,pl.w+2,pl.h+2))box(pl.x-cam,pl.y,pl.w+2,pl.h+2,'#28305b');}else{if(!draw(IMG.tile_platform,pl.x-cam,pl.y,pl.w+2,pl.h+2))box(pl.x-cam,pl.y,pl.w+2,pl.h+2,'#d6a04a');}});
    lamps.forEach(function(l,i){if(vis(l.x,42))draw(IMG.lamp_post,l.x-cam,l.baseY-92,38,92);});
    coins.forEach(function(c){if(c.taken||!vis(c.x-14,28))return;var yy=c.y+Math.sin(T*3+c.x)*4;if(!draw(IMG.coin_heart,c.x-14-cam,yy-14,28,28)){ctx.fillStyle='#e96b7d';ctx.beginPath();ctx.arc(c.x-cam,yy,8,0,Math.PI*2);ctx.fill();}});
    flags.forEach(function(f){if(!vis(f.x-20,40))return;var im=f.done?IMG.flag_on:IMG.flag_off;draw(im,f.x-20-cam,f.baseY-74,40,74);if(f.step===currentStep&&!f.done){ctx.strokeStyle='#ffd88b';ctx.lineWidth=2;ctx.beginPath();ctx.arc(Math.round(f.x-cam),Math.round(f.baseY-78),15+Math.sin(T*3)*2,0,Math.PI*2);ctx.stroke();}});
    if(vis(door.x-60,120)){draw(IMG.door_finish,door.x-60-cam,door.baseY-126,120,126);if(currentStep<3){ctx.fillStyle='rgba(16,23,53,.55)';ctx.fillRect(Math.round(door.x-34-cam),door.baseY-88,68,68);ctx.font='800 22px sans-serif';ctx.textAlign='center';ctx.fillStyle='#ffd88b';ctx.fillText('🔒',Math.round(door.x-cam),door.baseY-44);}}

    var img=heroFrame(),px=Math.round(P.x-cam+HERO_DRAW.ox),py=Math.round(P.y+HERO_DRAW.oy),dw=HERO_DRAW.w,dh=HERO_DRAW.h;
    if(P.face<0){ctx.save();ctx.translate(px+dw/2,0);ctx.scale(-1,1);ctx.translate(-(px+dw/2),0);}draw(img,px,py,dw,dh);if(P.face<0)ctx.restore();

    var n=near();if(promptEl){if(n){promptEl.hidden=false;promptEl.textContent=(n===door&&currentStep<3)?'🔒 Selesaikan 3 stasiun':'Tekan E / ✋';}else promptEl.hidden=true;}
    if(T<toastUntil){ctx.save();ctx.font='700 12px Poppins,sans-serif';ctx.textAlign='center';var tw=Math.min(310,ctx.measureText(toastText).width+34);ctx.fillStyle='rgba(18,24,55,.94)';ctx.strokeStyle='#ffd88b';ctx.lineWidth=2;rrect((W-tw)/2,74,tw,46,14);ctx.fill();ctx.stroke();ctx.fillStyle='#fff6df';ctx.fillText(toastText,W/2,102);ctx.restore();}}

  var bgmAudio=$('.js-bgm'),bgmSrc=$('.js-bgm-src'),bgmBtn=$('.js-music'),bgmWanted=true;function bgmUrl(){return bgmSrc?bgmSrc.textContent.trim():'';}function bgmSync(){if(!bgmAudio)return;var u=bgmUrl();if(u&&bgmAudio.getAttribute('src')!==u)bgmAudio.setAttribute('src',u);}function bgmPlay(){if(!bgmAudio||!bgmUrl())return;bgmSync();try{var pr=bgmAudio.play();if(pr&&pr.catch)pr.catch(function(){});}catch(e){}}if(bgmSrc&&'MutationObserver' in window)new MutationObserver(function(){bgmSync();if(bgmWanted&&bgmAudio&&bgmAudio.paused)bgmPlay();}).observe(bgmSrc,{childList:true,characterData:true,subtree:true});['pointerdown','touchstart'].forEach(function(ev){root.addEventListener(ev,function(){if(bgmWanted)bgmPlay();},{passive:true});});document.addEventListener('keydown',function(){if(bgmWanted)bgmPlay();});if(bgmBtn)bgmBtn.addEventListener('click',function(e){e.stopPropagation();bgmWanted=!bgmWanted;if(bgmAudio&&bgmUrl()){if(bgmWanted)bgmPlay();else bgmAudio.pause();}bgmBtn.textContent=bgmWanted?'♪':'×';bgmBtn.setAttribute('aria-pressed',bgmWanted?'true':'false');});
  updateProgress();var last=0;function loop(ts){var dt=Math.min(0.05,(ts-last)/1000||0.016);last=ts;if(overlay.hidden)update(dt);render();requestAnimationFrame(loop);}requestAnimationFrame(loop);
})();
